/**
 * Open the daily jackpot battle's awarded Craps seat on the page's Craps table.
 *
 * The jackpot battle is an ordinary craps-table field: an awarded wallet holds a seat in it, and
 * this module warms and opens that seat's verified replay (`prepareCrapsReplayTable`), with the
 * chain winner's payout overlaid so the result colour is exact.
 */

import { prepareCrapsReplayTable } from './replay-adapter.js';
import { crapsReplayFetch } from './replay-fetch.js';
import { CHAIN, CONTRACTS } from '../app/chain-config.js';
import { coinDrawResultTone } from '../app/coin-draw-centre.js';
import { fetchJSON } from '../app/api.js';

// The Craps panel imports the table under this pinned URL (app-craps-entry.js); loading it
// under any other URL would make a second module that defines the element twice.
const CRAPS_TABLE_MODULE = '../components/app-craps-table.js?rev=winnings-delivery-20261027';

const tableStyleLoads = new WeakMap();

/** Keep the table closed until its lazy stylesheet has actually loaded. */
function ensureTableStyles(doc, timeoutMs) {
  // The document owns the current asset URL. A retained module can contain an
  // older stylesheet hash after a CSS-only publish, so do not pin that URL here.
  const link = Array.from(doc?.querySelectorAll?.('link[rel="stylesheet"]') || []).find(candidate => {
    const source = candidate.getAttribute('data-href') || candidate.getAttribute('href') || '';
    return /\/(?:cache-[a-f0-9]{20}-)?craps-table\.css(?:[?#]|$)/i.test(source);
  });
  if (!link) return Promise.resolve(false);
  if (link.sheet) return Promise.resolve(true);
  if (tableStyleLoads.has(link)) return tableStyleLoads.get(link);
  const source = link.getAttribute('data-href') || link.getAttribute('href');
  // Preserve the retry URL for standalone tables whose link initially has href.
  if (!link.getAttribute('data-href')) link.setAttribute('data-href', source);
  const loaded = new Promise((resolve) => {
    const finish = (ready) => {
      clearTimeout(deadline);
      link.removeEventListener('load', onLoad);
      link.removeEventListener('error', onError);
      tableStyleLoads.delete(link);
      // Failed and timed-out requests must be retried on the next click.
      if (!ready) link.removeAttribute('href');
      resolve(ready);
    };
    const onLoad = () => finish(true);
    const onError = () => finish(false);
    const deadline = setTimeout(onError, timeoutMs);
    link.addEventListener('load', onLoad, { once: true });
    link.addEventListener('error', onError, { once: true });
    // Another loader may already have attached href while the CSS is in flight.
    if (!link.hasAttribute('href')) {
      const revision = String(link.dataset?.rev || '').trim();
      link.setAttribute('href', revision ? `${source}${source.includes('?') ? '&' : '?'}v=${encodeURIComponent(revision)}` : source);
    }
  });
  tableStyleLoads.set(link, loaded);
  return loaded;
}

async function readyTable(doc, timeoutMs) {
  const stylesReady = ensureTableStyles(doc, timeoutMs);
  const table = doc?.querySelector?.('app-craps-table');
  if (table?.open) return await stylesReady ? table : null;
  const defined = globalThis.customElements?.whenDefined?.('app-craps-table');
  if (!defined) return null;
  // Phones load the Craps panel one idle batch at a time, so the table can still be
  // missing when a battle is opened from the jackpot. Load it now instead of failing.
  const load = import(CRAPS_TABLE_MODULE).catch(() => null);
  let deadline;
  try {
    await Promise.race([Promise.all([defined, load]), new Promise((resolve) => { deadline = setTimeout(resolve, timeoutMs); })]);
  } finally { clearTimeout(deadline); }
  const upgraded = doc?.querySelector?.('app-craps-table');
  return await stylesReady && upgraded?.open ? upgraded : null;
}

const jackpotReplayPreparations = new Map();

async function readJackpotWinner(battleKey) {
  const day = Number(BigInt(battleKey) / 8n);
  const payload = await fetchJSON(`/game/craps/lobby/${day}/results`);
  // Winner identity remains valid even when exact total attribution is incomplete.
  return payload?.results?.find(row => row.lane === 'main'
    && String(row.battleKey).toLowerCase() === String(battleKey).toLowerCase()) ?? null;
}

function prepareJackpotReplay(battleKey, viewerBetId, prepareReplay, loadWinner = readJackpotWinner) {
  const key = `${CHAIN.id}:${CONTRACTS.CRAPS}:${String(battleKey).toLowerCase()}:${viewerBetId}`;
  const cached = jackpotReplayPreparations.get(key);
  if (cached?.prepareReplay === prepareReplay && cached?.loadWinner === loadWinner) return cached.promise;
  const entry = { prepareReplay, loadWinner, promise: null, settled: false };
  entry.promise = Promise.resolve().then(() => prepareReplay({ battleKey, viewerBetId, fetchImpl: crapsReplayFetch }))
    .then(async (prepared) => {
      // A main-lane winner is established by the actual payout event, never by
      // guessing from a seat's profit or the featured graph's current leader.
      if (prepared?.ready && prepared.mainModel) {
        const betId = prepared.pointer?.rankings?.main?.[0];
        const battlePaidWei = prepared.pointer?.prize?.mainPayoutWei;
        // Current chain replays already carry the exact payout and verified
        // winner. Avoid a second full-day results scan after building them.
        let winner = betId != null && battlePaidWei != null ? {
          betId, battlePaidWei,
          winner: prepared.featured?.players?.find(player => player.betId === betId)?.player,
        } : null;
        if (!winner) {
          try { winner = await loadWinner(battleKey); } catch { /* outcome remains unknown */ }
        }
        const tone = winner ? coinDrawResultTone({
          battleWonByViewer: String(winner.betId) === String(viewerBetId),
          viewerResult: prepared.mainModel.tableOptions.viewerResult,
        }) : null;
        const original = prepared;
        prepared = { ...original, resultTone: tone, open(table) {
          original.open({ open(options) {
            table.open({ ...options, ...(winner ? {
              battleWinnerBetId: winner.betId,
              ...(winner.winner ? { battleWinner: winner.winner } : {}),
              battleWonByViewer: String(winner.betId) === String(viewerBetId),
              battlePayoutWei: String(winner.battlePaidWei),
            } : {}) });
          } });
        } };
      }
      if (!prepared?.ready && jackpotReplayPreparations.get(key) === entry) jackpotReplayPreparations.delete(key);
      return prepared;
    }, (error) => {
      if (jackpotReplayPreparations.get(key) === entry) jackpotReplayPreparations.delete(key);
      throw error;
    }).finally(() => {
      entry.settled = true;
      for (const [oldKey, old] of jackpotReplayPreparations) {
        if (jackpotReplayPreparations.size <= 4) break;
        if (oldKey !== key && old.settled) jackpotReplayPreparations.delete(oldKey);
      }
    });
  jackpotReplayPreparations.set(key, entry);
  return entry.promise;
}

/** Warm only the awarded seat. No table opens and no seen/acknowledged state changes. */
export async function preloadJackpotDrawRun({
  battleKey, viewerBetId, doc = globalThis.document,
  tableTimeoutMs = 12_000, prepareReplay = prepareCrapsReplayTable, loadWinner = readJackpotWinner,
} = {}) {
  const [table, prepared] = await Promise.all([
    readyTable(doc, tableTimeoutMs), prepareJackpotReplay(battleKey, viewerBetId, prepareReplay, loadWinner),
  ]);
  return { ready: Boolean(table && prepared?.ready), resultTone: prepared?.resultTone ?? null };
}

/** The current draw awards an ordinary Craps seat; open its prepared verified replay. */
export async function openJackpotDrawRun({
  battleKey, viewerBetId, opener = null, doc = globalThis.document,
  tableTimeoutMs = 12_000, signal = null, prepareReplay = prepareCrapsReplayTable, loadWinner = readJackpotWinner,
} = {}) {
  if (signal?.aborted) return { ok: false, message: 'Battle opening canceled.' };
  const [table, result] = await Promise.all([
    readyTable(doc, tableTimeoutMs), prepareJackpotReplay(battleKey, viewerBetId, prepareReplay, loadWinner),
  ]);
  if (!table) return { ok: false, message: 'The Craps table is still loading. Try again in a moment.' };
  if (signal?.aborted) return { ok: false, message: 'Battle opening canceled.' };
  let opened = false;
  const guardedTable = { open(options) {
    if (signal?.aborted) return;
    table.open(options, opener);
    opened = true;
  } };
  if (result?.ready) result.open(guardedTable);
  return { ok: opened, resultTone: opened ? result.resultTone ?? null : null, message: opened ? '' : result?.ready
    ? 'Battle opening canceled.' : 'The battle is still settling. Try again shortly.' };
}
